import{_ as t,o,c as r,a2 as i}from"./chunks/framework.DHtetOlu.js";const u=JSON.parse('{"title":"External circuit","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/circuit.md","filePath":"en/guide/circuit.md"}'),a={name:"en/guide/circuit.md"};function c(n,e,s,d,l,h){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="external-circuit" tabindex="-1">External circuit <a class="header-anchor" href="#external-circuit" aria-label="Permalink to &quot;External circuit&quot;">​</a></h1><p>Real coils are driven by circuits: a voltage source with a series resistance, a transformer with a load, a capacitor discharging into a coil. MagFEM solves the <strong>field and the circuit together</strong>, in a single system of equations (strong coupling), in transient analysis.</p><h2 id="creating-the-circuit" tabindex="-1">Creating the circuit <a class="header-anchor" href="#creating-the-circuit" aria-label="Permalink to &quot;Creating the circuit&quot;">​</a></h2><ol><li>The <code>+</code> next to <strong>Model</strong> creates a <strong>Circuit</strong>, which opens in a tab with the schematic.</li><li>The schematic already has a <strong>Coil (FEM)</strong> block for each circuit of the Mesh: it is the coil of the field model, with its inductance and coupling computed by the FEM.</li><li>From the schematic toolbar, add <strong>voltage or current sources</strong>, <strong>resistors</strong>, <strong>inductors</strong>, <strong>capacitors</strong> and the <strong>Ground</strong> (required).</li><li>Click a terminal and then another one to connect a <strong>wire</strong>. Drag the blocks to arrange them and the wire segments to change the route.</li></ol><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>W</code></td><td>wire mode</td></tr><tr><td><code>R</code></td><td>rotate the component</td></tr><tr><td><code>M</code></td><td>mirror</td></tr><tr><td><code>Del</code></td><td>delete</td></tr><tr><td>mouse wheel</td><td>zoom</td></tr></tbody></table><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>A source has amplitude, frequency, phase and DC level, or an <strong>expression in t</strong> (in seconds) that can use the project variables: <code>V0*sin(2*pi*60*t)</code>, <code>24</code> for DC, <code>24*min(1, t/0.001)</code> for a fast (1 ms) ramp. Expressions use <code>+ - * / ^</code>, <code>pi</code> and functions such as <code>sin</code>, <code>cos</code>, <code>exp</code>, <code>sqrt</code>, <code>abs</code>, <code>min</code> and <code>max</code>.</p><h2 id="solving-and-viewing-signals" tabindex="-1">Solving and viewing signals <a class="header-anchor" href="#solving-and-viewing-signals" aria-label="Permalink to &quot;Solving and viewing signals&quot;">​</a></h2><p>Solve the field physics with <strong>transient</strong> analysis: the schematic coils receive the circuit current at every step. After solving, click a component to see <strong>i(t)</strong> and <strong>v(t)</strong>; marked signals show up below the schematic.</p><p>Typical examples:</p><ul><li><strong>RL circuit</strong>: voltage source, resistor and the coil. The current rises with the time constant L/R, with L coming from the FEM (and changing if the steel saturates).</li><li><strong>Transformer</strong>: voltage source on the primary and a resistive load on the secondary. With perfect coupling, V2 = (N2/N1)·V1.</li></ul><div class="tip custom-block"><p class="custom-block-title">Circuit from code</p><p>To also couple <strong>motion</strong> (a plunger moving under the magnetic force), use the <a href="./../scripting/bridge.html">local bridge</a>: the <a href="./../scripting/examples.html#contactor">contactor</a> example integrates circuit, field and mechanics in a Python loop.</p></div>',12)])])}const m=t(a,[["render",c]]);export{u as __pageData,m as default};
